#!/usr/bin/env bash
set -euo pipefail

# Build/verification imports must not write generated bytecode into source.
export PYTHONDONTWRITEBYTECODE=1
target=${1:?target}; output=${2:?output}
build_dir=$(cd "$(dirname "$0")" && pwd)
root=$(cd "$build_dir/../.." && pwd)
python3 - "$target" "$output" "$root" <<'PY'
import json, os, subprocess, sys
target, output, root = sys.argv[1:]
try:
    app_version = json.load(open(os.path.join(root, "frontend", "package.json"), encoding="utf-8"))["version"]
except (OSError, KeyError, json.JSONDecodeError):
    app_version = "unknown"
components = [
    {"name":"replicaro", "version":app_version, "type":"application"},
    {"name":"restic", "version":"0.19.1", "type":"application", "scope":"required"},
    {"name":"kopia", "version":"0.23.1", "type":"application", "scope":"required"},
    {"name":"rclone", "version":"1.75.1", "type":"application", "scope":"required"},
]
try:
    raw = subprocess.check_output(["go", "list", "-m", "-json", "all"], cwd=os.path.join(root, "backend"), text=True)
    decoder, offset = json.JSONDecoder(), 0
    while offset < len(raw):
        module, offset = decoder.raw_decode(raw, offset)
        while offset < len(raw) and raw[offset].isspace(): offset += 1
        path, version = module.get("Path", ""), module.get("Version", "")
        if path and path != "github.com/local/replicaro":
            components.append({"name":path, "version":version, "type":"library", "scope":"required", "purl":"pkg:golang/%s@%s" % (path, version)})
except (OSError, subprocess.SubprocessError, json.JSONDecodeError):
    pass
try:
    lock = json.load(open(os.path.join(root, "frontend", "package-lock.json"), encoding="utf-8"))
    for location, package in lock.get("packages", {}).items():
        if not location.startswith("node_modules/") or not package.get("version"):
            continue
        name = location[len("node_modules/"):]
        scope = "excluded" if package.get("dev") else ("optional" if package.get("optional") else "required")
        components.append({"name":name, "version":package["version"], "type":"library", "scope":scope, "purl":"pkg:npm/%s@%s" % (name, package["version"])})
except (OSError, json.JSONDecodeError):
    pass
bom = {"bomFormat":"CycloneDX", "specVersion":"1.5", "version":1,
       "metadata":{"component":{"name":"replicaro", "version":app_version, "type":"application"}, "properties":[{"name":"replicaro.target","value":target}]},
       "components":components}
with open(output,"w",encoding="utf-8") as f:
    json.dump(bom,f,sort_keys=True,separators=(",",":")); f.write("\n")
PY
